	private static RowState row(NativeLmdbQuerySource source, NativeCancellationToken cancellation) {
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("s", 0, "p", 1, "o", 2), null);
		layout.freeze(List.of("s", "p", "o"));
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance(), (TupleExpr) null, cancellation);
		assertTrue(LmdbNativeAggregateCompiler.initializeRow(row, row.base, source, layout));
		return row;
	}

